package cn.gov.document.platform.writing.api;import cn.gov.document.platform.common.api.ApiResponse;import cn.gov.document.platform.writing.application.WritingQaService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/writing-tasks/{taskId}/qa")public class WritingQaController{private final WritingQaService service;public WritingQaController(WritingQaService service){this.service=service;}@PostMapping ApiResponse<WritingQaDtos.Response>ask(@PathVariable String taskId,@Valid @RequestBody WritingQaDtos.QuestionRequest request){return ApiResponse.success(service.ask(taskId,request));}@GetMapping ApiResponse<List<WritingQaDtos.Response>>list(@PathVariable String taskId){return ApiResponse.success(service.list(taskId));}}
